void hw_dac_convert (UInt16 dac_value)
{	
	CRITICAL; 

	C_ENTER;
	{
		if (dac_value < 0x400)
			DACR = ((dac_value << 6) & (0x3FF << 6)) ;
	}
	C_LEAVE;
	
}
